1	// Package contractsentinel report: content-addressed, persistable audit reports.
2	package contractsentinel
3	
4	import (
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"fmt"
9		"os"
10		"path/filepath"
11		"sort"
12		"strings"
13		"unicode/utf8"
14	)
15	
16	// Check statuses recorded per rule in a report.
17	const (
18		StatusUnchecked   = "未检查"
19		StatusPass        = "通过"
20		StatusDefect      = "发现缺陷"
21		StatusToolMissing = "工具缺失"
22		StatusTimeout     = "超时"
23	)
24	
25	// ReportArtifact identifies the audited artifact by name and content hash.
26	type ReportArtifact struct {
27		Name string `json:"name"`
28		Hash string `json:"hash"`
29	}
30	
31	// ReportRule is one rule together with the invariant check result. The note
32	// carries the original checker description: counterexample evidence for a
33	// defect, a tool availability remark for 工具缺失, a deadline remark for 超时,
34	// or an optional remark for a passing check. It is empty for reports built
35	// only from invariant booleans.
36	type ReportRule struct {
37		ID          string `json:"id"`
38		Kind        string `json:"kind"`
39		Severity    string `json:"severity"`
40		Invariant   string `json:"invariant"`
41		RequiresABI bool   `json:"requiresABI"`
42		Version     string `json:"version"`
43		Status      string `json:"status"`
44		Note        string `json:"note,omitempty"`
45	}
46	
47	// ReportFinding binds a defect to its artifact, rule, version and evidence.
48	type ReportFinding struct {
49		ArtifactHash string `json:"artifactHash"`
50		RuleID       string `json:"ruleId"`
51		Version      string `json:"version"`
52		Severity     string `json:"severity"`
53		Invariant    string `json:"invariant"`
54		Evidence     string `json:"evidence"`
55	}
56	
57	// Report is the persisted audit result.
58	type Report struct {
59		ReportID string          `json:"reportId"`
60		Artifact ReportArtifact  `json:"artifact"`
61		Rules    []ReportRule    `json:"rules"`
62		Findings []ReportFinding `json:"findings"`
63	}
64	
65	// wireArtifact is the JSON shape of an artifact in an audit submission.
66	type wireArtifact struct {
67		Name     string `json:"name"`
68		ABI      string `json:"abi"`
69		Bytecode string `json:"bytecode"`
70		Source   string `json:"source"`
71	}
72	
73	// wireRule is the JSON shape of a rule in an audit submission.
74	type wireRule struct {
75		ID          string `json:"id"`
76		Kind        string `json:"kind"`
77		Severity    string `json:"severity"`
78		Invariant   string `json:"invariant"`
79		RequiresABI bool   `json:"requiresABI"`
80		Version     string `json:"version"`
81	}
82	
83	// CheckRecord is one imported per-rule check result: the artifact hash and
84	// rule version it was produced against, the conclusion status, and the
85	// original checker note (counterexample, tool or deadline remark).
86	type CheckRecord struct {
87		ArtifactHash string
88		RuleID       string
89		Version      string
90		Status       string
91		Note         string
92	}
93	
94	// wireCheck is the JSON shape of one entry in the checks array.
95	type wireCheck struct {
96		ArtifactHash string `json:"artifactHash"`
97		RuleID       string `json:"ruleId"`
98		Version      string `json:"version"`
99		Status       string `json:"status"`
100		Note         string `json:"note"`
101	}
102	
103	// wireInput is the JSON object accepted by the audit command.
104	type wireInput struct {
105		Artifact   wireArtifact               `json:"artifact"`
106		Rules      []wireRule                 `json:"rules"`
107		Invariants map[string]json.RawMessage `json:"invariants"`
108		Checks     []wireCheck                `json:"checks"`
109	}
110	
111	// submissionShape is the fixed-field shape of an audit submission: the agreed
112	// spellings at the top level and inside the artifact, every rule and every
113	// check record. The invariants object is a fixed top-level member but has no
114	// nested shape, so it passes through untouched: invariant names are
115	// user-defined rather than fixed fields, and "Inv" and "inv" stay two
116	// independent invariants and a padded name is not trimmed.
117	var submissionShape = fixedShape{
118		keys: []string{"artifact", "rules", "invariants", "checks"},
119		objects: map[string]fixedShape{
120			"artifact": {keys: []string{"name", "abi", "bytecode", "source"}},
121		},
122		arrays: map[string]fixedShape{
123			"rules":  {keys: []string{"id", "kind", "severity", "invariant", "requiresABI", "version"}},
124			"checks": {keys: []string{"artifactHash", "ruleId", "version", "status", "note"}},
125		},
126	}
127	
128	// strictSubmissionJSON rewrites submission bytes to the fixed submission
129	// fields under their agreed spelling; see fixedShape for the recognition
130	// convention shared with the archive read side.
131	func strictSubmissionJSON(data []byte) ([]byte, error) {
132		return strictFixedJSON(data, submissionShape)
133	}
134	
135	// validateFormalCheckStatuses checks the formal "status" member of every
136	// strict check record. The strict rewrite dropped extension members, so the
137	// status seen here is the agreed-spelling one alone: a missing formal status,
138	// a non-string one, or an unsupported value rejects the whole submission
139	// even when an adjacent "StAtus" extension member carried a legal-looking
140	// value. The error names the rule the record is for so the offending entry is
141	// identifiable.
142	func validateFormalCheckStatuses(strict []byte) error {
143		var top struct {
144			Checks []map[string]json.RawMessage `json:"checks"`
145		}
146		if err := json.Unmarshal(strict, &top); err != nil {
147			return errInvalid("invalid JSON: " + err.Error())
148		}
149		for _, rec := range top.Checks {
150			where := "check record"
151			if raw, ok := rec["ruleId"]; ok {
152				var ruleID string
153				if err := json.Unmarshal(raw, &ruleID); err == nil && ruleID != "" {
154					where = "check for rule " + ruleID
155				}
156			}
157			raw, ok := rec["status"]
158			if !ok {
159				return errInvalid(where + ": status is required")
160			}
161			var status string
162			if err := json.Unmarshal(raw, &status); err != nil {
163				return errInvalid(where + ": status must be a string")
164			}
165			if !validCheckStatus(status) {
166				return errInvalid(where + ": unknown status " + status)
167			}
168		}
169		return nil
170	}
171	
172	// validateFormalRequiresABI checks the formal "requiresABI" member of every
173	// strict rule definition in an audit submission; the written-means-boolean
174	// rule and the per-rule walk are shared with the archive side in
175	// checkRuleFieldTypes. The strict rewrite dropped extension members, so the
176	// value seen here is the agreed-spelling one alone. Decoding the member
177	// straight into a Go bool would turn null into the zero value false: a rule
178	// whose requirement was never actually stated would be recorded as not
179	// needing an ABI, indistinguishable from an explicit false, and could even
180	// produce a defect finding from a false invariant. When the formal member is
181	// present its value must be the JSON boolean true or false — null, a string,
182	// a number, an object or an array rejects the whole submission, whether or
183	// not the artifact carries an ABI and whether or not the rule received any
184	// check conclusion. An omitted member still means false. A case-variant or
185	// whitespace-padded name is extension data and its value, null included,
186	// never reaches this check; it can neither trigger the error nor rescue an
187	// illegal formal value. The error names the rule so the offending entry is
188	// identifiable and is an input error.
189	func validateFormalRequiresABI(strict []byte) error {
190		return checkRuleFieldTypes(strict,
191			[]ruleFieldTypeCheck{{field: "requiresABI", typ: ruleFieldBoolean}},
192			ruleFieldTypeHooks{
193				locate: func(_ int, rule map[string]json.RawMessage) string {
194					if id := formalRuleID(rule); id != "" {
195						return "rule " + id
196					}
197					return "rule"
198				},
199				invalidJSON: func(err error) error { return errInvalid("invalid JSON: " + err.Error()) },
200				reject: func(where, field string, typ ruleFieldType) error {
201					return errInvalid(where + ": " + field + " " + typ.requirement())
202				},
203			})
204	}
205	
206	// artifactTextFields lists the formal artifact members whose value, once the
207	// member is written out, must be a JSON string.
208	var artifactTextFields = []string{"name", "abi", "bytecode", "source"}
209	
210	// validateFormalArtifactFields checks the raw JSON token of every written
211	// formal artifact member before the strict submission is decoded into the Go
212	// wireArtifact string fields. Decoding straight into a Go string turns a
213	// formal null member into the zero value "", indistinguishable from an
214	// omitted member or an explicitly written empty string: an artifact with a
215	// legal name and "source":null and no rules that need the ABI or bytecode
216	// would then hash exactly like one whose source was submitted as "", pass
217	// every business check and receive a success report, laundering a malformed
218	// submission into a legal one. Whenever a formal member is present its value
219	// must therefore be a JSON string — null, a boolean, a number, an object or
220	// an array rejects the whole submission, independently of the rules array,
221	// the check records and of whether any rule references the field. The check
222	// is about the JSON type alone, not non-empty text: an omitted member still
223	// decodes to its default and an explicit "" keeps the ordinary business
224	// judgement (an empty name still produces no report, a rule that needs an
225	// ABI still needs a non-empty one, a symbolic rule still needs non-empty
226	// bytecode, and legal empty text is otherwise accepted). The strict rewrite
227	// dropped extension members, so a case-variant or whitespace-padded name
228	// ("Source", " source ") neither fills a missing formal field nor rescues an
229	// illegal formal value; names written with Unicode escapes are compared
230	// after decoding, so "source":null names the same formal source field.
231	// The error names the exact field, e.g. "artifact.source". An absent or null
232	// artifact object is left untouched here: the existing "artifact name is
233	// required" business error keeps covering it.
234	func validateFormalArtifactFields(strict []byte) error {
235		var top struct {
236			Artifact json.RawMessage `json:"artifact"`
237		}
238		if err := json.Unmarshal(strict, &top); err != nil {
239			return errInvalid("invalid JSON: " + err.Error())
240		}
241		if len(top.Artifact) == 0 || string(top.Artifact) == "null" {
242			return nil
243		}
244		var artifact map[string]json.RawMessage
245		if err := json.Unmarshal(top.Artifact, &artifact); err != nil {
246			return errInvalid("invalid JSON: " + err.Error())
247		}
248		for _, field := range artifactTextFields {
249			raw, present := artifact[field]
250			if !present {
251				continue
252			}
253			var token any
254			if err := json.Unmarshal(raw, &token); err != nil {
255				return errInvalid("artifact." + field + " must be a string")
256			}
257			if _, ok := token.(string); !ok {
258				return errInvalid("artifact." + field + " must be a string")
259			}
260		}
261		return nil
262	}
263	
264	// ParseAuditInput decodes an audit submission JSON object into domain values.
265	// Invariant values must be JSON booleans; any other type is an error. A formal
266	// requiresABI member on a rule must likewise be a JSON boolean: null or any
267	// non-boolean value rejects the whole submission instead of being read as the
268	// zero value false, while an omitted member still means false. Each formal
269	// artifact member (name, abi, bytecode, source) that is written out must be a
270	// JSON string: null or any non-string value rejects the whole submission
271	// instead of being read as the zero value "", while an omitted member still
272	// takes its default and an explicit empty string keeps the ordinary business
273	// judgement. Any JSON object in the submission that repeats a member name
274	// rejects the whole submission: the decoder keeps only the last value
275	// silently, so a repeated invariant key would choose a conclusion by member
276	// order instead of giving one trustworthy result. A character the decoder
277	// would silently rewrite — an invalid UTF-8 byte, or an unpaired or wrongly
278	// ordered surrogate escape in any member name or string value, including
279	// values nested under unknown extension members — rejects the whole
280	// submission as an input error before any content is hashed, so evidence and
281	// hashes always reflect the submitted bytes rather than a U+FFFD-rewritten
282	// copy. Only the fixed fields under their agreed spelling participate: case
283	// variants and whitespace-padded names are extension data and are ignored, so
284	// they can neither override a formal value nor supply one when the formal
285	// member is missing or unsupported. Invariant names are not fixed fields —
286	// they are user-defined, compared case sensitively and never trimmed.
287	func ParseAuditInput(data []byte) (Artifact, []Rule, map[string]bool, []CheckRecord, error) {
288		if charErr := validateJSONCharacters(data); charErr != nil {
289			return Artifact{}, nil, nil, nil, errInvalid(charErr.Error())
290		}
291		if dup := findDuplicateJSONMember(data); dup != nil {
292			return Artifact{}, nil, nil, nil, errInvalid(duplicateMemberMessage(data, dup))
293		}
294		strict, err := strictSubmissionJSON(data)
295		if err != nil {
296			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
297		}
298		if err := validateFormalCheckStatuses(strict); err != nil {
299			return Artifact{}, nil, nil, nil, err
300		}
301		if err := validateFormalRequiresABI(strict); err != nil {
302			return Artifact{}, nil, nil, nil, err
303		}
304		if err := validateFormalArtifactFields(strict); err != nil {
305			return Artifact{}, nil, nil, nil, err
306		}
307		var in wireInput
308		if err := json.Unmarshal(strict, &in); err != nil {
309			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
310		}
311		invariants := make(map[string]bool, len(in.Invariants))
312		for key, raw := range in.Invariants {
313			// Only JSON true/false is a conclusion. Unmarshalling directly into a
314			// bool would turn null into the zero value false, which would falsely
315			// record a defect; require the token to be a boolean instead.
316			var token any
317			if err := json.Unmarshal(raw, &token); err != nil {
318				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
319			}
320			holds, ok := token.(bool)
321			if !ok {
322				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
323			}
324			invariants[key] = holds
325		}
326		artifact := Artifact{
327			Name:     in.Artifact.Name,
328			ABI:      in.Artifact.ABI,
329			Bytecode: in.Artifact.Bytecode,
330			Source:   in.Artifact.Source,
331		}
332		rules := make([]Rule, 0, len(in.Rules))
333		for _, wr := range in.Rules {
334			rules = append(rules, Rule{
335				ID:          wr.ID,
336				Kind:        wr.Kind,
337				Severity:    wr.Severity,
338				Invariant:   wr.Invariant,
339				RequiresABI: wr.RequiresABI,
340				Version:     wr.Version,
341			})
342		}
343		checks := make([]CheckRecord, 0, len(in.Checks))
344		for _, wc := range in.Checks {
345			checks = append(checks, CheckRecord{
346				ArtifactHash: wc.ArtifactHash,
347				RuleID:       wc.RuleID,
348				Version:      wc.Version,
349				Status:       wc.Status,
350				Note:         wc.Note,
351			})
352		}
353		return artifact, rules, invariants, checks, nil
354	}
355	
356	// ArtifactHash computes the content hash of an artifact. Only the raw ABI,
357	// bytecode and source strings contribute; field boundaries are explicit
358	// (length-prefixed) so that different splits never collide. The source is
359	// hashed as a field value, never read from disk, and the name does not
360	// participate.
361	func ArtifactHash(a Artifact) string {
362		h := sha256.New()
363		h.Write([]byte("contractsentinel-artifact-v1\n"))
364		for _, field := range []string{a.ABI, a.Bytecode, a.Source} {
365			fmt.Fprintf(h, "%d\n", len(field))
366			h.Write([]byte(field))
367		}
368		sum := h.Sum(nil)
369		return hex.EncodeToString(sum)
370	}
371	
372	// validCheckStatus reports whether status is one of the four recorded check
373	// conclusions.
374	func validCheckStatus(status string) bool {
375		switch status {
376		case StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
377			return true
378		}
379		return false
380	}
381	
382	// BuildReport evaluates rules against the artifact and invariant values and
383	// imported check records and produces the report to persist. Insufficient
384	// inputs (missing ABI for a rule that requires it, missing bytecode for a
385	// symbolic rule) fail the whole submission and are never recorded as defects.
386	// Imported checks are validated as a whole: unknown rules, duplicate records,
387	// unknown statuses, missing notes, hash or version mismatches, and a rule
388	// receiving both a check record and an invariant boolean all reject the
389	// submission without producing a report.
390	func BuildReport(artifact Artifact, rules []Rule, invariants map[string]bool, checks []CheckRecord) (Report, error) {
391		if artifact.Name == "" {
392			return Report{}, errInvalid("artifact name is required")
393		}
394		hash := ArtifactHash(artifact)
395		seen := make(map[string]bool, len(rules))
396		ruleByID := make(map[string]Rule, len(rules))
397		for _, rule := range rules {
398			if rule.ID == "" {
399				return Report{}, errInvalid("rule id is required")
400			}
401			if rule.Version == "" {
402				return Report{}, errInvalid("rule " + rule.ID + " version is required")
403			}
404			if seen[rule.ID] {
405				return Report{}, errInvalid("duplicate rule id " + rule.ID)
406			}
407			seen[rule.ID] = true
408			ruleByID[rule.ID] = rule
409			if rule.RequiresABI && artifact.ABI == "" {
410				return Report{}, errInvalid("rule " + rule.ID + " requires an ABI")
411			}
412			if rule.Kind == "symbolic" && artifact.Bytecode == "" {
413				return Report{}, errInvalid("symbolic rule " + rule.ID + " requires bytecode")
414			}
415		}
416		checkByRule := make(map[string]CheckRecord, len(checks))
417		for _, check := range checks {
418			if check.RuleID == "" {
419				return Report{}, errInvalid("check rule id is required")
420			}
421			rule, ok := ruleByID[check.RuleID]
422			if !ok {
423				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown rule")
424			}
425			if _, dup := checkByRule[check.RuleID]; dup {
426				return Report{}, errInvalid("duplicate check for rule " + check.RuleID)
427			}
428			if check.ArtifactHash != hash {
429				return Report{}, errInvalid("check for rule " + check.RuleID + ": artifact hash mismatch")
430			}
431			if check.Version != rule.Version {
432				return Report{}, errInvalid("check for rule " + check.RuleID + ": version mismatch")
433			}
434			if !validCheckStatus(check.Status) {
435				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown status " + check.Status)
436			}
437			if check.Status != StatusPass && strings.TrimSpace(check.Note) == "" {
438				return Report{}, errInvalid("check for rule " + check.RuleID + ": note is required for status " + check.Status)
439			}
440			if _, hasInvariant := invariants[rule.Invariant]; hasInvariant {
441				return Report{}, errInvalid("rule " + check.RuleID + ": both a check record and an invariant value are provided")
442			}
443			checkByRule[check.RuleID] = check
444		}
445		report := Report{
446			Artifact: ReportArtifact{Name: artifact.Name, Hash: hash},
447			Rules:    []ReportRule{},
448			Findings: []ReportFinding{},
449		}
450		for _, rule := range rules {
451			status := StatusUnchecked
452			note := ""
453			if check, ok := checkByRule[rule.ID]; ok {
454				status = check.Status
455				note = check.Note
456			} else {
457				// No imported check: the invariant booleans decide. The verdict
458				// interpretation is shared with the finding-list path in Run.
459				switch checkInvariant(rule, invariants) {
460				case invariantHolds:
461					status = StatusPass
462				case invariantViolated:
463					status = StatusDefect
464				}
465			}
466			report.Rules = append(report.Rules, ReportRule{
467				ID:          rule.ID,
468				Kind:        rule.Kind,
469				Severity:    rule.Severity,
470				Invariant:   rule.Invariant,
471				RequiresABI: rule.RequiresABI,
472				Version:     rule.Version,
473				Status:      status,
474				Note:        note,
475			})
476			if status == StatusDefect {
477				evidence := note
478				if evidence == "" {
479					evidence = invariantEvidence(rule.Invariant)
480				}
481				report.Findings = append(report.Findings, ReportFinding{
482					ArtifactHash: hash,
483					RuleID:       rule.ID,
484					Version:      rule.Version,
485					Severity:     rule.Severity,
486					Invariant:    rule.Invariant,
487					Evidence:     evidence,
488				})
489			}
490		}
491		report.ReportID = ReportID(report)
492		return report, nil
493	}
494	
495	// canonicalReport is the deterministic content a report id is computed from.
496	// The rules and findings are the report's own ReportRule and ReportFinding
497	// values: their stored JSON fields are exactly the content the id binds, so
498	// the id form reuses the one field representation instead of maintaining a
499	// parallel copy that every field change would have to be mirrored into. The
500	// rule note keeps its omitempty behaviour, so a note omitted and a note
501	// written as an empty string hash alike and reports built only from invariant
502	// booleans keep their original ids.
503	type canonicalReport struct {
504		ArtifactHash string          `json:"artifactHash"`
505		Name         string          `json:"name"`
506		Rules        []ReportRule    `json:"rules"`
507		Findings     []ReportFinding `json:"findings"`
508	}
509	
510	// canonicalize renders a report into its order-independent form. The rule and
511	// finding slices are copied before sorting, so computing an id never reorders
512	// the report itself: a saved report keeps the submission order and a loaded
513	// report keeps the archive order.
514	func canonicalize(report Report) canonicalReport {
515		cr := canonicalReport{
516			ArtifactHash: report.Artifact.Hash,
517			Name:         report.Artifact.Name,
518		}
519		cr.Rules = append(cr.Rules, report.Rules...)
520		sort.Slice(cr.Rules, func(i, j int) bool { return cr.Rules[i].ID < cr.Rules[j].ID })
521		cr.Findings = append(cr.Findings, report.Findings...)
522		sort.Slice(cr.Findings, func(i, j int) bool { return cr.Findings[i].RuleID < cr.Findings[j].RuleID })
523		return cr
524	}
525	
526	// ReportID returns the content-addressed identifier of a report. The id binds
527	// the artifact hash, name, complete rule definitions, the invariant value
528	// used by each rule (unchecked and explicit pass are distinct), and the
529	// findings. Rule order, invariant key order and unrelated invariant keys do
530	// not influence it.
531	func ReportID(r Report) string {
532		data, err := json.Marshal(canonicalize(r))
533		if err != nil {
534			panic(err) // canonical values are all strings and bools
535		}
536		sum := sha256.Sum256(data)
537		return hex.EncodeToString(sum[:])
538	}
539	
540	// validateReport checks every archive legality condition against r. It is the
541	// single definition of a legal report: the id and artifact hash are 64
542	// lowercase hex characters, the id matches the content, the artifact name is
543	// present, rule ids are present and unique with non-empty versions, statuses
544	// use the five recorded values, tool-missing and timeout notes are
545	// non-blank, and 发现缺陷 rules correspond one-to-one with findings whose
546	// artifact hash, version, severity, invariant and evidence match the rule.
547	// The same conditions apply to submissions and to stored archives: a
548	// recomputed id never makes an invalid report legal. fail is errInvalid for
549	// submissions and errCorrupt for stored archives.
550	func validateReport(r Report, fail func(string) error) error {
551		if !validReportID(r.ReportID) {
552			return fail("report id " + r.ReportID + " is not a 64-character lowercase hex string")
553		}
554		if r.Artifact.Name == "" {
555			return fail("report " + r.ReportID + " artifact name is required")
556		}
557		if !validReportID(r.Artifact.Hash) {
558			return fail("report " + r.ReportID + " artifact hash is not a 64-character lowercase hex string")
559		}
560		if ReportID(r) != r.ReportID {
561			return fail("report content does not match id " + r.ReportID)
562		}
563		seenRule := make(map[string]bool, len(r.Rules))
564		defectByID := make(map[string]ReportRule)
565		for _, rule := range r.Rules {
566			if rule.ID == "" {
567				return fail("report " + r.ReportID + " has a rule with an empty id")
568			}
569			if seenRule[rule.ID] {
570				return fail("report " + r.ReportID + " has duplicate rule id " + rule.ID)
571			}
572			seenRule[rule.ID] = true
573			if rule.Version == "" {
574				return fail("report " + r.ReportID + " rule " + rule.ID + " has an empty version")
575			}
576			switch rule.Status {
577			case StatusUnchecked, StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
578			default:
579				return fail("report " + r.ReportID + " rule " + rule.ID + " has unknown status " + rule.Status)
580			}
581			if (rule.Status == StatusToolMissing || rule.Status == StatusTimeout) && strings.TrimSpace(rule.Note) == "" {
582				return fail("report " + r.ReportID + " rule " + rule.ID + " status " + rule.Status + " has no note")
583			}
584			if rule.Status == StatusDefect {
585				defectByID[rule.ID] = rule
586			}
587		}
588		seenFinding := make(map[string]bool, len(r.Findings))
589		for _, f := range r.Findings {
590			if f.RuleID == "" {
591				return fail("report " + r.ReportID + " has a finding with an empty rule id")
592			}
593			rule, ok := defectByID[f.RuleID]
594			if !ok {
595				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " does not match a 发现缺陷 rule")
596			}
597			if seenFinding[f.RuleID] {
598				return fail("report " + r.ReportID + " has a duplicate finding for rule " + f.RuleID)
599			}
600			seenFinding[f.RuleID] = true
601			if f.ArtifactHash != r.Artifact.Hash {
602				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has artifact hash " + f.ArtifactHash + ", want " + r.Artifact.Hash)
603			}
604			if f.Version != rule.Version {
605				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has version " + f.Version + ", want " + rule.Version)
606			}
607			if f.Severity != rule.Severity {
608				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has severity " + f.Severity + ", want " + rule.Severity)
609			}
610			if f.Invariant != rule.Invariant {
611				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has invariant " + f.Invariant + ", want " + rule.Invariant)
612			}
613			wantEvidence := rule.Note
614			if wantEvidence == "" {
615				wantEvidence = invariantEvidence(rule.Invariant)
616			}
617			if f.Evidence != wantEvidence {
618				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has evidence " + f.Evidence + ", want " + wantEvidence)
619			}
620		}
621		for id := range defectByID {
622			if !seenFinding[id] {
623				return fail("report " + r.ReportID + " defect rule " + id + " has no finding")
624			}
625		}
626		return nil
627	}
628	
629	// validStoredReport validates archive contents.
630	func validStoredReport(r Report) error {
631		return validateReport(r, func(msg string) error { return errCorrupt(msg) })
632	}
633	
634	// validSubmittedReport validates a submission before any store operation.
635	func validSubmittedReport(r Report) error {
636		return validateReport(r, func(msg string) error { return errInvalid(msg) })
637	}
638	
639	// firstInvalidUTF8ByteInString returns the first byte that is not valid UTF-8
640	// inside s. A Go string can carry any bytes, including bytes no JSON text may
641	// contain: json.Marshal (and therefore the canonical marshalling inside
642	// ReportID) silently replaces such a byte with U+FFFD instead of failing, so
643	// neither the id/content check nor the archive round trip can see it.
644	func firstInvalidUTF8ByteInString(s string) (byte, bool) {
645		for i := 0; i < len(s); {
646			r, size := utf8.DecodeRuneInString(s[i:])
647			if r == utf8.RuneError && size == 1 {
648				return s[i], true
649			}
650			i += size
651		}
652		return 0, false
653	}
654	
655	// validateSubmittedText is the in-memory counterpart of the JSON character
656	// gates in ParseAuditInput and loadStoredReport. SaveReport accepts a Report
657	// built directly by a Go caller, whose strings never passed through JSON
658	// decoding; encoding/json marshals such a value without an error while
659	// replacing every invalid UTF-8 byte with U+FFFD, and ReportID computes from
660	// the same rewritten canonical form, so the recomputed id and the
661	// rule/finding correspondence would all match an archive whose text no
662	// longer equals what the caller handed over. Every caller-supplied string is
663	// therefore checked on the raw object — reportId, artifact name and hash,
664	// each rule definition field and status note, and each finding binding field
665	// and evidence — independently of which rules produced defects and of
666	// whether the report carries any finding at all. The rejection is an input
667	// error naming the exact field, with the array position of rules and
668	// findings, and it runs before any filesystem operation.
669	func validateSubmittedText(r Report) error {
670		check := func(field, value string) error {
671			if b, bad := firstInvalidUTF8ByteInString(value); bad {
672				return errInvalid(fmt.Sprintf("invalid UTF-8 byte 0x%02x in report field %s", b, field))
673			}
674			return nil
675		}
676		if err := check("reportId", r.ReportID); err != nil {
677			return err
678		}
679		if err := check("artifact.name", r.Artifact.Name); err != nil {
680			return err
681		}
682		if err := check("artifact.hash", r.Artifact.Hash); err != nil {
683			return err
684		}
685		ruleFields := []string{"id", "kind", "severity", "invariant", "version", "status", "note"}
686		for i, rule := range r.Rules {
687			values := []string{rule.ID, rule.Kind, rule.Severity, rule.Invariant, rule.Version, rule.Status, rule.Note}
688			for j, value := range values {
689				if err := check(fmt.Sprintf("rules[%d].%s", i, ruleFields[j]), value); err != nil {
690					return err
691				}
692			}
693		}
694		findingFields := []string{"artifactHash", "ruleId", "version", "severity", "invariant", "evidence"}
695		for i, finding := range r.Findings {
696			values := []string{finding.ArtifactHash, finding.RuleID, finding.Version, finding.Severity, finding.Invariant, finding.Evidence}
697			for j, value := range values {
698				if err := check(fmt.Sprintf("findings[%d].%s", i, findingFields[j]), value); err != nil {
699					return err
700				}
701			}
702		}
703		return nil
704	}
705	
706	// duplicateArchiveError classifies an archive that repeats a JSON member as
707	// corrupt and names the requested report id, the decoded member name and the
708	// object carrying it (with array position and rule id when applicable).
709	func duplicateArchiveError(id string, data []byte, dup *duplicateMemberError) error {
710		return errCorrupt("report " + id + " archive is corrupt: " + duplicateMemberMessage(data, dup))
711	}
712	
713	// characterArchiveError classifies an archive whose bytes are not legal JSON
714	// text — an invalid UTF-8 byte anywhere, or an unpaired / wrongly ordered
715	// surrogate escape inside any member name or string value, including unknown
716	// extension members — as corrupt and names the requested report id together
717	// with the precise byte offset, line/column and JSON path. It is the
718	// read-side counterpart of the submission gate in ParseAuditInput: the decode
719	// below would otherwise replace both problems with U+FFFD and could accept a
720	// rewritten archive whose id and rule/finding evidence happened to match.
721	func characterArchiveError(id string, charErr *charEncodingError) error {
722		return errCorrupt("report " + id + " archive is corrupt: " + charErr.Error())
723	}
724	
725	// reportShape is the fixed-field shape of a stored report archive: the agreed
726	// spellings at the top level and inside the artifact, every rule and every
727	// finding. The trusted content of a report is carried by these fixed fields
728	// alone; case variants, whitespace-padded names and unknown members are
729	// extension data and never reach the decoder.
730	var reportShape = fixedShape{
731		keys: []string{"reportId", "artifact", "rules", "findings"},
732		objects: map[string]fixedShape{
733			"artifact": {keys: []string{"name", "hash"}},
734		},
735		arrays: map[string]fixedShape{
736			"rules":    {keys: []string{"id", "kind", "severity", "invariant", "requiresABI", "version", "status", "note"}},
737			"findings": {keys: []string{"artifactHash", "ruleId", "version", "severity", "invariant", "evidence"}},
738		},
739	}
740	
741	// strictReportJSON rewrites archive bytes to the fixed report fields under
742	// their original spelling; see fixedShape for the recognition convention
743	// shared with the submission side.
744	func strictReportJSON(data []byte) ([]byte, error) {
745		return strictFixedJSON(data, reportShape)
746	}
747	
748	// validateArchiveRuleFields is the read-side counterpart of the submission
749	// gate in validateFormalRequiresABI. A ReportRule's typed members are Go
750	// bool/string fields, so decoding the strict archive straight into Report
751	// turns a formal null member into the zero value false or "": an archive that
752	// wrote "requiresABI":null, or "note":null on a passing rule without a note,
753	// would read byte-for-byte like one that omitted the member, the recomputed
754	// id and the rule/finding correspondence would all pass on that laundered
755	// value, and a diff could even compare the rule as unchanged. The shared
756	// checkRuleFieldTypes gate therefore inspects each written formal member's
757	// raw JSON token before that decoding happens. null or any other
758	// non-required type makes the whole archive corrupt, independently of the
759	// rule's check status and of whether it has a finding — the offending rule is
760	// never skipped and no partial report is returned. An omitted member still
761	// decodes to the zero value and an explicit empty string is still judged by
762	// the ordinary business rules: the string gate is about the JSON type alone,
763	// not about requiring text to be non-empty. The strict rewrite dropped
764	// extension members, so a case-variant or whitespace-padded name is invisible
765	// here: a correctly typed value it carries neither supplies nor rescues the
766	// formal value, and a null it carries never reaches this gate. locate renders
767	// the rule locator in the wording each gate historically used, and every
768	// error names the requested report id and is classified as archive
769	// corruption.
770	func validateArchiveRuleFields(strict []byte, id string, checks []ruleFieldTypeCheck,
771		locate func(int, map[string]json.RawMessage) string) error {
772		return checkRuleFieldTypes(strict, checks, ruleFieldTypeHooks{
773			locate: locate,
774			invalidJSON: func(err error) error {
775				return errCorrupt("invalid JSON in report " + id + ": " + err.Error())
776			},
777			reject: func(where, field string, typ ruleFieldType) error {
778				return errCorrupt("report " + id + " archive is corrupt: " + where + ": " + field + " " + typ.requirement())
779			},
780		})
781	}
782	
783	// archiveRuleLocator names a rule in an archive error by its formal id
784	// ("rule r-bad"), falling back to "rule" when the id is missing, empty or not
785	// itself a legal string. It deliberately carries no rules-array position.
786	func archiveRuleLocator(_ int, rule map[string]json.RawMessage) string {
787		if ruleID := formalRuleID(rule); ruleID != "" {
788			return "rule " + ruleID
789		}
790		return "rule"
791	}
792	
793	// archiveRulePositionLocator names a rule's position in the rules array
794	// ("rules[1]") and, when the rule carries a legal non-empty id, also names it
795	// ("rules[1] (rule r-bad)").
796	func archiveRulePositionLocator(i int, rule map[string]json.RawMessage) string {
797		where := fmt.Sprintf("rules[%d]", i)
798		if ruleID := formalRuleID(rule); ruleID != "" {
799			where += " (rule " + ruleID + ")"
800		}
801		return where
802	}
803	
804	// validateArchiveRequiresABI runs the read-side boolean gate for the formal
805	// requiresABI member.
806	func validateArchiveRequiresABI(strict []byte, id string) error {
807		return validateArchiveRuleFields(strict, id,
808			[]ruleFieldTypeCheck{{field: "requiresABI", typ: ruleFieldBoolean}},
809			archiveRuleLocator)
810	}
811	
812	// archiveRuleTextFields lists the formal rule members whose value, once the
813	// member is written out, must be a JSON string.
814	var archiveRuleTextFields = []string{"id", "kind", "severity", "invariant", "version", "status", "note"}
815	
816	// validateArchiveRuleText runs the read-side string gate for the text fields
817	// of every stored rule; see validateArchiveRuleFields for why the raw token is
818	// checked before decoding.
819	func validateArchiveRuleText(strict []byte, id string) error {
820		checks := make([]ruleFieldTypeCheck, len(archiveRuleTextFields))
821		for i, field := range archiveRuleTextFields {
822			checks[i] = ruleFieldTypeCheck{field: field, typ: ruleFieldString}
823		}
824		return validateArchiveRuleFields(strict, id, checks, archiveRulePositionLocator)
825	}
826	
827	// loadStoredReport parses archive bytes for id and fully validates them.
828	func loadStoredReport(data []byte, id string) (Report, error) {
829		// Read-side counterpart of the submission character gate in
830		// ParseAuditInput. As with a repeated member, json.Unmarshal silently
831		// rewrites an invalid UTF-8 byte and an unpaired or wrongly ordered
832		// surrogate escape into U+FFFD, so an archive whose note and evidence both
833		// carried the substitution character could have those two spots changed to
834		// lone surrogate escapes and still decode to byte-identical content: the
835		// recomputed id and the rule/finding evidence comparison would then pass on
836		// the rewritten copy. Every raw string literal is checked first — member
837		// names and values, at every depth, inside unknown extension members too —
838		// and the whole archive is corrupt when any character is illegal, whatever
839		// id the rewritten content would compute.
840		if charErr := validateJSONCharacters(data); charErr != nil {
841			return Report{}, characterArchiveError(id, charErr)
842		}
843		// Read-side counterpart of the submission check: json.Unmarshal silently
844		// keeps the last value for a repeated member, so an archive that writes a
845		// rule status as 发现缺陷 and then 通过 would decode to whichever came
846		// last. The recomputed id and the rule/finding correspondence all operate
847		// on that last-wins value and could therefore pass, accepting an archive
848		// with two conflicting conclusions. Any repeated member in any object
849		// makes the archive corrupt, regardless of the last value.
850		if dup := findDuplicateJSONMember(data); dup != nil {
851			return Report{}, duplicateArchiveError(id, data, dup)
852		}
853		strict, err := strictReportJSON(data)
854		if err != nil {
855			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
856		}
857		// Check the formal requiresABI member against its raw JSON token before
858		// decoding into the Go bool below; otherwise a null value would silently
859		// become the zero value false and could pass every later check, including
860		// the content id, as if the archive had explicitly said false.
861		if err := validateArchiveRequiresABI(strict, id); err != nil {
862			return Report{}, err
863		}
864		// Same laundering hazard for the rule text fields: decoding into a Go
865		// string turns a formal null member into "", so an archive that wrote
866		// "note":null on a note-less passing rule would pass every later check,
867		// including the content id, as if the member had been omitted. Check the
868		// raw JSON token of every written formal text member before decoding.
869		if err := validateArchiveRuleText(strict, id); err != nil {
870			return Report{}, err
871		}
872		var r Report
873		if err := json.Unmarshal(strict, &r); err != nil {
874			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
875		}
876		if r.ReportID != id {
877			return Report{}, errCorrupt("report id " + r.ReportID + " does not match requested id " + id)
878		}
879		if err := validStoredReport(r); err != nil {
880			return Report{}, err
881		}
882		return r, nil
883	}
884	
885	// saveReportHook, when set, is invoked after the archive existence check and
886	// before the atomic publish. It lets tests simulate another process racing to
887	// claim the same report id.
888	var saveReportHook func(finalPath string)
889	
890	// SaveReport persists a report under the store directory. The store is safe
891	// for concurrent writers: identical reports share one file and all
892	// submissions succeed, different reports never overwrite each other, and
893	// readers only ever observe complete files. A submission is fully validated
894	// before any store operation, so an invalid report creates no store and no
895	// files. Every string in a directly constructed report must be valid UTF-8:
896	// json.Marshal would otherwise rewrite an invalid byte to U+FFFD while the
897	// content-addressed id matched the rewritten copy, reporting success for an
898	// archive whose text differs from the caller's; such a report is rejected as
899	// an input error before the store directory is touched. A pre-existing file
900	// with the same id must be a valid archive of the same report; a corrupted
901	// archive makes the submission fail while keeping the original file, even
902	// when the corruption appears only during the save. The first successfully
903	// archived bytes are never replaced by later submissions.
904	func SaveReport(dir string, r Report) error {
905		if err := validateSubmittedText(r); err != nil {
906			return err
907		}
908		if err := validSubmittedReport(r); err != nil {
909			return err
910		}
911		if err := os.MkdirAll(dir, 0o755); err != nil {
912			return err
913		}
914		finalPath := filepath.Join(dir, r.ReportID+".json")
915		if existing, err := os.ReadFile(finalPath); err == nil {
916			if _, err := loadStoredReport(existing, r.ReportID); err != nil {
917				return err
918			}
919			return nil
920		} else if !os.IsNotExist(err) {
921			return err
922		}
923		data, err := json.Marshal(r)
924		if err != nil {
925			return err
926		}
927		tmp, err := os.CreateTemp(dir, ".report-*.tmp")
928		if err != nil {
929			return err
930		}
931		tmpPath := tmp.Name()
932		cleanup := func() { os.Remove(tmpPath) }
933		if _, err := tmp.Write(data); err != nil {
934			tmp.Close()
935			cleanup()
936			return err
937		}
938		if err := tmp.Sync(); err != nil {
939			tmp.Close()
940			cleanup()
941			return err
942		}
943		if err := tmp.Close(); err != nil {
944			cleanup()
945			return err
946		}
947		if saveReportHook != nil {
948			saveReportHook(finalPath)
949		}
950		if err := os.Link(tmpPath, finalPath); err != nil {
951			cleanup()
952			if os.IsExist(err) {
953				existing, readErr := os.ReadFile(finalPath)
954				if readErr != nil {
955					return readErr
956				}
957				if _, err := loadStoredReport(existing, r.ReportID); err != nil {
958					return err
959				}
960				return nil
961			}
962			return err
963		}
964		cleanup()
965		return nil
966	}
967	
968	// LoadReport reads and verifies a report by id. The id must be 64 lowercase
969	// hex characters; missing, corrupted or tampered archives produce a clear
970	// error. The store is only read, never created or modified.
971	func LoadReport(dir, id string) (Report, error) {
972		if !validReportID(id) {
973			return Report{}, errInvalid("invalid report id " + id + ": want 64 lowercase hex characters")
974		}
975		data, err := os.ReadFile(filepath.Join(dir, id+".json"))
976		if err != nil {
977			if os.IsNotExist(err) {
978				return Report{}, errNotFound("report " + id + " not found")
979			}
980			return Report{}, err
981		}
982		return loadStoredReport(data, id)
983	}
984	
985	type errNotFound string
986	
987	func (e errNotFound) Error() string { return string(e) }
988	
989	type errCorrupt string
990	
991	func (e errCorrupt) Error() string { return string(e) }
992

