23	// 所有检查状态及没有 finding 的报告。错误点名报告标识、出错字段与规则数组
24	// 位置，规则有合法非空 id 时同时点名该规则。省略字段仍沿用默认值与必填校验，
25	// 显式空字符串仍按既有业务规则判断；大小写变体、带空格名称与未知扩展成员
26	// 继续被忽略，其中的 null 不触发本错误，也不能替代或挽救非法的正式成员。
27	
28	// jsonEscapedN is the six-character JSON unicode escape that decodes to the
29	// letter n; it is built by concatenation so the source never carries the
30	// escape-looking literal as one piece.
31	const jsonEscapedN = `\` + `u006e`
32	
33	// mutateRuleTextField 把归档中指定规则的某个文本成员替换为 raw 片段
34	// （如 null）；该成员不存在时把它插入到 id 成员之后。fragment 为空串表示
35	// 删除整个成员。
36	func mutateRuleTextField(t *testing.T, doc, ruleID, field, fragment string) string {
37		t.Helper()
38		idMember := `"id":"` + ruleID + `"`
39		idIdx := strings.Index(doc, idMember)
40		if idIdx < 0 {
41			t.Fatalf("test setup: rule %s not found in archive", ruleID)
42		}
43		ruleEnd := strings.IndexByte(doc[idIdx:], '}')
44		if ruleEnd < 0 {
45			t.Fatalf("test setup: rule %s object has no end", ruleID)
46		}
47		ruleEnd += idIdx
48		marker := `"` + field + `":`
49		at := strings.Index(doc[idIdx:ruleEnd], marker)
50		if at < 0 {
51			if fragment == "" {
52				t.Fatalf("test setup: rule %s has no %s member to remove", ruleID, field)
53			}
54			idEnd := idIdx + len(idMember)
55			return doc[:idEnd] + `,"` + field + `":` + fragment + doc[idEnd:]
56		}
57		at += idIdx
58		valueStart := at + len(marker)
59		var valueEnd int
60		if doc[valueStart] == '"' {
61			// 测试夹具中的字符串值不含转义引号，下一个引号即结束。
62			closing := strings.IndexByte(doc[valueStart+1:], '"')
63			if closing < 0 {
64				t.Fatalf("test setup: rule %s %s value has no closing quote", ruleID, field)
65			}
66			valueEnd = valueStart + 1 + closing + 1
67		} else {
68			end := strings.IndexAny(doc[valueStart:], ",}")
69			if end < 0 {
70				t.Fatalf("test setup: rule %s %s value has no end", ruleID, field)
71			}
72			valueEnd = valueStart + end
73		}
74		if fragment == "" {
75			// 删除整个成员：优先连同后随逗号，否则连同前导逗号。
76			if valueEnd < len(doc) && doc[valueEnd] == ',' {
77				return doc[:at] + doc[valueEnd+1:]
78			}
79			return doc[:at-1] + doc[valueEnd:]
80		}
81		return doc[:at] + `"` + field + `":` + fragment + doc[valueEnd:]
82	}
83	
84	// writeArchiveWithRuleText marshals a legal report, rewrites one rule text
85	// member with a raw fragment, recomputes the report id from the decoded
86	// content and writes the archive under that id. A null fragment launders
87	// through the plain decoder (null decodes into the string zero value), so the
88	// recomputed id keeps the archive self-consistent and rejection can only come
89	// from the type gate. Other non-string JSON types never unmarshal into a Go
90	// string, so the original id is kept: it may mismatch, but the type gate runs
91	// before the id comparison and rejects with the same corruption error.
92	func writeArchiveWithRuleText(t *testing.T, dir string, r Report, ruleID, field, fragment string) string {
93		t.Helper()
94		r.ReportID = ReportID(r)
95		data, err := json.Marshal(r)
96		if err != nil {
97			t.Fatal(err)
98		}
99		doc := mutateRuleTextField(t, string(data), ruleID, field, fragment)
100		if doc == string(data) {
101			t.Fatal("test setup: mutation did not change the archive")
102		}
103		id := r.ReportID
104		if strict, err := strictReportJSON([]byte(doc)); err == nil {
105			var decoded Report
106			if err := json.Unmarshal(strict, &decoded); err == nil {
107				newID := ReportID(decoded)
108				doc = strings.Replace(doc, `"reportId":"`+id+`"`, `"reportId":"`+newID+`"`, 1)
109				id = newID
110			}
111		}
112		if err := os.WriteFile(filepath.Join(dir, id+".json"), []byte(doc), 0o644); err != nil {
113			t.Fatal(err)
114		}
115		return id
116	}
