118	// expectCorruptRuleTextLoad asserts the full read-side contract for a
119	// non-string formal rule text member: errCorrupt naming the report id, the
120	// array position, the field and the string requirement (plus the rule id when
121	// the rule carries a legal one), a zero report and an untouched archive.
122	func expectCorruptRuleTextLoad(t *testing.T, dir, id, position, rule, field string) {
123		t.Helper()
124		path := filepath.Join(dir, id+".json")
125		before, err := os.ReadFile(path)
126		if err != nil {
127			t.Fatal(err)
128		}
129		got, err := LoadReport(dir, id)
130		if err == nil {
131			t.Fatalf("a non-string formal %s must reject the whole archive, got %+v", field, got)
132		}
133		var ec errCorrupt
134		if !errors.As(err, &ec) {
135			t.Fatalf("illegal %s classifies as errCorrupt, got %T: %v", field, err, err)
136		}
137		msg := err.Error()
138		if !strings.Contains(msg, id) {
139			t.Fatalf("error must name the report id %q: %v", id, err)
140		}
141		if !strings.Contains(msg, position) {
142			t.Fatalf("error must name the rule array position %q: %v", position, err)
143		}
144		if rule != "" && !strings.Contains(msg, rule) {
145			t.Fatalf("error must name the offending rule %q: %v", rule, err)
146		}
147		if !strings.Contains(msg, field+" must be a string") {
148			t.Fatalf("error must state %s must be a string: %v", field, err)
149		}
150		if !reflect.DeepEqual(got, Report{}) {
151			t.Fatalf("failed read must return the zero report, got %+v", got)
152		}
153		after, err := os.ReadFile(path)
154		if err != nil {
155			t.Fatalf("corrupt archive must not be deleted: %v", err)
156		}
157		if string(after) != string(before) {
158			t.Fatal("failed read must not rewrite or repair the archive")
159		}
160	}
