515				t.Fatal("diff against the corrupt side must keep failing")
516			}
517			kept, err := os.ReadFile(filepath.Join(dir, badID+".json"))
518			if err != nil {
519				t.Fatal(err)
520			}
521			if !bytes.Contains(kept, []byte(`"note":null`)) {
522				t.Fatalf("failed diff must leave the corrupt archive untouched:\n%s", kept)
523			}
524		}
525	
526		// 恢复另一侧后比较成功：证明失败只来自类型关，且成功的比较同样不重写
527		// 归档，既有合法报告的比较分类与统计保持不变。
528		if err := os.WriteFile(filepath.Join(dir, otherID+".json"), cleanOther, 0o644); err != nil {
529			t.Fatal(err)
