1	package contractsentinel
2	
3	import (
4		"errors"
5		"strings"
6		"testing"
7	)
8	
9	// 本文件锁定 audit 提交中规则定义 requiresABI 成员的类型规则：正式成员
10	// （约定拼写，含 Unicode 转义写法）一旦出现，值必须是 JSON 布尔值 true 或
11	// false。null、字符串、数字、对象或数组都使整份提交失败，而不是被解码成
12	// 零值 false 后按“不需要 ABI”继续——否则一处写错的输入会与显式 false
13	// 得到相同的报告标识，用户无法区分。省略 requiresABI 仍按 false 处理；
14	// 大小写变体或两侧带空格的名称是扩展信息，其中的 null 不触发本错误，也
15	// 不能挽救正式成员的非法值。
16	
17	// requiresABIDoc 拼装一份只含单条规则的提交，ruleJSON 是规则对象的完整
18	// JSON；artifact 默认不带 ABI，便于验证“无 ABI 时显式 false 仍合法”。
19	func requiresABIDoc(ruleJSON, abi string) string {
20		return `{"artifact":{"name":"Vault","abi":"` + abi + `","bytecode":"0x1","source":"Vault.sol"},` +
21			`"rules":[` + ruleJSON + `],` +
22			`"invariants":{"inv":true}}`
23	}
24	
25	// requiresABIRule 给出一条合法规则，requiresABI 片段由调用者原样插入
