3	import (
4		"encoding/json"
5		"errors"
6		"strings"
7		"testing"
8	)
9	
10	// 本文件锁定 audit 提交中产物四个正式字段 name、abi、bytecode、source 的
11	// 类型规则：成员一旦写出，值必须是 JSON 字符串。null、布尔值、数字、对象
12	// 或数组都使整份提交失败（errInvalid），错误点名具体字段，例如
13	// artifact.source，并说明该字段必须是字符串，而不是被解码成零值 "" 后按
14	// 空文本继续——否则产物名称合法、规则为空、source 为 null 这样的畸形提交
15	// 会与用户明确提交空文本得到相同的产物哈希和成功报告，格式错误与合法
16	// 空文本混在一起。校验与规则数组、检查记录、规则是否引用该字段无关。
17	// 省略成员仍取默认零值，显式空字符串仍走原有业务判断（空名称不能出报告、
18	// 需要 ABI 的规则仍要求非空 ABI、符号规则仍要求非空字节码）；大小写变体
19	// 与带空格的名称只是扩展信息，不能补上缺失的正式字段或挽救非法值；
20	// Unicode 转义写出的正式名称解码后受同一检查。合法字符串逐字保留。
21	
22	// jsonString quotes a Go string as a JSON string literal, so tests can embed
23	// text containing newlines, tabs and CJK characters without hand-escaping.
24	func jsonString(s string) string {
25		b, err := json.Marshal(s)
26		if err != nil {
27			panic(err)
28		}
29		return string(b)
30	}
31	
32	// artifactFieldsDoc 拼装一份提交：nameJSON 与 fieldsJSON 是 artifact 对象
33	// 的内部 JSON 片段（均可为空），rulesJSON 是单条规则的完整 JSON，空串表示
34	// 规则数组为空。
35	func artifactFieldsDoc(nameJSON, fieldsJSON, rulesJSON string) string {
36		inner := nameJSON
37		if fieldsJSON != "" {
38			if inner != "" {
39				inner += ","
40			}
41			inner += fieldsJSON
42		}
43		rules := "[]"
44		if rulesJSON != "" {
45			rules = "[" + rulesJSON + "]"
46		}
47		return `{"artifact":{` + inner + `},"rules":` + rules + `}`
48	}
49	
50	// artifactTextRule 是一条不要求 ABI 的普通静态规则，供“有规则时类型检查
51	// 也不省略”的用例使用。
52	const artifactTextRule = `{"id":"r1","kind":"static","severity":"high","invariant":"inv","requiresABI":false,"version":"1.0.0"}`
53	
54	// --- 核心场景：名称合法、source 为 null、规则为空也必须整份拒绝 ---
55	
56	func TestParseAuditNullSourceWithEmptyRulesRejected(t *testing.T) {
57		in := artifactFieldsDoc(`"name":"Vault"`, `"abi":"","bytecode":"","source":null`, "")
58		artifact, rules, invariants, checks, err := ParseAuditInput([]byte(in))
59		if err == nil {
60			t.Fatal("a legal name with source null and no rules must still reject the submission")
61		}
62		var ei errInvalid
63		if !errors.As(err, &ei) {
64			t.Fatalf("a type error is a submission format error (errInvalid), got %T: %v", err, err)
65		}
66		if !strings.Contains(err.Error(), "artifact.source") {
67			t.Fatalf("error must name the exact field artifact.source: %v", err)
68		}
69		if !strings.Contains(err.Error(), "must be a string") {
70			t.Fatalf("error must state the field must be a string: %v", err)
71		}
72		if artifact != (Artifact{}) || rules != nil || invariants != nil || checks != nil {
73			t.Fatalf("rejection must return no partial data: %+v %+v %+v %+v", artifact, rules, invariants, checks)
74		}
75	}
76	
77	// --- 四个字段的 null 都整份拒绝，且与是否有规则、是否有检查记录无关 ---
78	
79	func TestParseAuditNullArtifactFieldsRejected(t *testing.T) {
80		for _, tc := range []struct {
81			field string
82			doc   string
83		}{
84			{"name", artifactFieldsDoc(`"name":null`, `"abi":"a","bytecode":"b","source":"s"`, "")},
85			{"abi", artifactFieldsDoc(`"name":"Vault"`, `"abi":null,"bytecode":"b","source":"s"`, "")},
86			{"bytecode", artifactFieldsDoc(`"name":"Vault"`, `"abi":"a","bytecode":null,"source":"s"`, "")},
87			{"source", artifactFieldsDoc(`"name":"Vault"`, `"abi":"a","bytecode":"b","source":null`, "")},
88		} {
89			t.Run(tc.field, func(t *testing.T) {
90				// 无规则、无检查记录：不能因此省略类型校验。
91				if _, _, _, _, err := ParseAuditInput([]byte(tc.doc)); err == nil ||
92					!strings.Contains(err.Error(), "artifact."+tc.field) ||
93					!strings.Contains(err.Error(), "must be a string") {
94					t.Fatalf("null %s must reject and name artifact.%s: %v", tc.field, tc.field, err)
95				}
96				// 有规则（且规则并不引用该字段）时同样拒绝。
97				withRule := strings.Replace(tc.doc, `"rules":[]`, `"rules":[`+artifactTextRule+`]`, 1)
98				if _, _, _, _, err := ParseAuditInput([]byte(withRule)); err == nil ||
99					!strings.Contains(err.Error(), "artifact."+tc.field+" must be a string") {
100					t.Fatalf("null %s must reject even with an unrelated rule present: %v", tc.field, err)
101				}
102			})
103		}
104	}
105	
106	// --- 布尔值、数字、对象、数组同样整份拒绝，不能被当成空字符串 ---
107	
108	func TestParseAuditNonStringArtifactFieldsRejected(t *testing.T) {
109		values := []string{"true", "false", "0", "123", "{}", `["x"]`}
110		docs := map[string]func(string) string{
111			"name":     func(val string) string { return `{"artifact":{"name":` + val + `},"rules":[]}` },
112			"abi":      func(val string) string { return `{"artifact":{"name":"Vault","abi":` + val + `},"rules":[]}` },
113			"bytecode": func(val string) string { return `{"artifact":{"name":"Vault","bytecode":` + val + `},"rules":[]}` },
114			"source":   func(val string) string { return `{"artifact":{"name":"Vault","source":` + val + `},"rules":[]}` },
115		}
116		for _, field := range []string{"name", "abi", "bytecode", "source"} {
117			for _, val := range values {
118				t.Run(field+"/"+val, func(t *testing.T) {
119					_, _, _, _, err := ParseAuditInput([]byte(docs[field](val)))
120					if err == nil {
121						t.Fatalf("artifact %s=%s must reject the whole submission", field, val)
122					}
123					if !strings.Contains(err.Error(), "artifact."+field+" must be a string") {
124						t.Fatalf("error must name artifact.%s and the string requirement: %v", field, err)
125					}
126				})
127			}
128		}
129	}
