131	// --- 省略成员仍取默认值；显式空字符串合法；两种写法的产物哈希一致 ---
132	
133	func TestParseAuditArtifactFieldsOmittedAndExplicitEmpty(t *testing.T) {
134		omitted := `{"artifact":{"name":"Vault"},"rules":[]}`
135		aOmit, _, _, _, err := ParseAuditInput([]byte(omitted))
136		if err != nil {
137			t.Fatalf("omitted artifact fields must keep their defaults: %v", err)
138		}
139		if aOmit.ABI != "" || aOmit.Bytecode != "" || aOmit.Source != "" {
140			t.Fatalf("omitted fields must decode to empty strings: %+v", aOmit)
141		}
142	
143		explicitEmpty := artifactFieldsDoc(`"name":"Vault"`, `"abi":"","bytecode":"","source":""`, "")
144		aEmpty, _, _, _, err := ParseAuditInput([]byte(explicitEmpty))
145		if err != nil {
146			t.Fatalf("explicit empty strings must stay legal: %v", err)
147		}
148		if aEmpty != aOmit {
149			t.Fatalf("omitted and explicit-empty must decode to the same artifact:\n%+v\n%+v", aEmpty, aOmit)
150		}
151		if ArtifactHash(aEmpty) != ArtifactHash(aOmit) {
