155		// 合法空文本在没有相关要求时可以出报告，且两种写法报告标识一致。
156		rOmit := strictParsedReport(t, omitted)
157		rEmpty := strictParsedReport(t, explicitEmpty)
158		if rOmit.ReportID != rEmpty.ReportID {
