163	// --- 显式空字符串保留原有业务判断 ---
164	
165	func TestParseAuditExplicitEmptyKeepsBusinessJudgement(t *testing.T) {
166		// 显式空名称：解析合法，但不能生成报告。
167		emptyName := `{"artifact":{"name":"","abi":"","bytecode":"","source":""},"rules":[]}`
168		a, rules, inv, checks, err := ParseAuditInput([]byte(emptyName))
169		if err != nil {
