177		// 需要 ABI 的规则 + 显式空 ABI：仍是既有 ABI 业务错误，不是类型错误。
178		emptyABI := artifactFieldsDoc(`"name":"Vault"`, `"abi":"","bytecode":"b","source":"s"`,
