21	// injectRuleTextField reads the archive named by id, locates the rule object
22	// with ruleID and rewrites the formal field member with the raw fragment
23	// (e.g. `null`); a rule that does not carry the member gets it inserted right
24	// after the id member. The mutated bytes are written back and returned so
25	// tests can assert the failed read leaves them untouched.
26	func injectRuleTextField(t *testing.T, store, id, ruleID, field, fragment string) []byte {
27		t.Helper()
28		path := filepath.Join(store, id+".json")
29		data, err := os.ReadFile(path)
30		if err != nil {
31			t.Fatal(err)
32		}
33		doc := string(data)
34		idMember := `"id":"` + ruleID + `"`
35		idIdx := strings.Index(doc, idMember)
36		if idIdx < 0 {
37			t.Fatalf("test setup: rule %s not found in archive", ruleID)
38		}
39		ruleEnd := strings.IndexByte(doc[idIdx:], '}')
40		if ruleEnd < 0 {
41			t.Fatalf("test setup: rule %s object has no end", ruleID)
42		}
43		ruleEnd += idIdx
44		marker := `"` + field + `":`
45		at := strings.Index(doc[idIdx:ruleEnd], marker)
46		var out string
47		if at < 0 {
48			idEnd := idIdx + len(idMember)
49			out = doc[:idEnd] + `,"` + field + `":` + fragment + doc[idEnd:]
50		} else {
51			at += idIdx
52			valueStart := at + len(marker)
53			var valueEnd int
54			if doc[valueStart] == '"' {
55				closing := strings.IndexByte(doc[valueStart+1:], '"')
56				if closing < 0 {
57					t.Fatalf("test setup: rule %s %s value has no closing quote", ruleID, field)
58				}
59				valueEnd = valueStart + 1 + closing + 1
60			} else {
61				end := strings.IndexAny(doc[valueStart:], ",}")
62				if end < 0 {
63					t.Fatalf("test setup: rule %s %s value has no end", ruleID, field)
64				}
65				valueEnd = valueStart + end
66			}
67			out = doc[:at] + `"` + field + `":` + fragment + doc[valueEnd:]
68		}
69		if out == doc {
70			t.Fatal("test setup: injection did not change the archive")
71		}
72		if err := os.WriteFile(path, []byte(out), 0o644); err != nil {
73			t.Fatal(err)
74		}
75		return []byte(out)
76	}
