			}
			if stdout != "" {
				t.Fatalf("stdout must stay empty:\n%s", stdout)
			}
			if !strings.Contains(stderr, "artifact.source must be a string") {
				t.Fatalf("stderr must name the formal field and its type:\n%s", stderr)
			}
		})
	}
}

