// --- 与该规则是否被检查、是否产生缺陷无关：缺陷、通过、未检查、带检查记录都拒绝 ---

func TestParseAuditNullRuleTextRejectedForEveryConclusion(t *testing.T) {
	hash := ArtifactHash(strictTestArtifact())

