	// 也不能挽救提交，且这不是缺陷结论。
	checked := ruleTextDefaultFields()
	checked["id"] = `"r-checked"`
	checked["invariant"] = `"inv-checked"`
	checked["severity"] = `null`
	check := fmt.Sprintf(
		`{"artifactHash":%q,"ruleId":"r-checked","version":"1.0.0","status":"发现缺陷","note":"counterexample: x"}`,
